template exportShapesModule*(T: typedesc) =
  ## Defines `shapes_module`'s exported symbols over the handlers of `T`.
  proc shapesModuleKitCreate(init: ModuleInit): Result[pointer, InvocationFailure] {.nimcall, gcsafe, raises: [].} =
    let r = initModule(T, init)
    if r.isErr:
      return err(r.error)
    let instance = r.get
    if instance.isNil:
      return err(moduleError("initModule returned nil"))
    GC_ref(instance)
    ok(cast[pointer](instance))

  proc shapesModuleKitDispose(p: pointer) {.nimcall, gcsafe, raises: [].} =
    let instance {.cursor.} = cast[T](p)
    when compiles(destroyModule(instance)):
      destroyModule(instance)
    GC_unref(instance)

  proc shapesModuleKitName(): cstring {.exportc: "logos_shapes_module_MODULE_name", dynlib, cdecl, gcsafe, raises: [].} =
    system.cstring(moduleName)

  proc shapesModuleKitInit(input: ptr LogosModuleInitInput, outContext: ptr ptr LogosModuleContext): LogosResult {.exportc: "logos_shapes_module_MODULE_init", dynlib, cdecl, gcsafe, raises: [].} =
    kitEnter()
    kitInit(input, outContext, declaresEvents, shapesModuleKitCreate)

  proc shapesModuleKitDestroy(module: ptr LogosModuleContext) {.exportc: "logos_shapes_module_MODULE_destroy", dynlib, cdecl, gcsafe, raises: [].} =
    kitEnter()
    kitDestroy(module, shapesModuleKitDispose)

  proc shapesModuleKitRoute(p: pointer, bare: string, params: openArray[byte]): Result[seq[byte], InvocationFailure] {.nimcall, gcsafe, raises: [].} =
    let instance {.cursor.} = cast[T](p)
    routeShapesModule(instance, bare, params)

  proc shapesModuleKitCallSurface(outLen: ptr csize_t): ptr uint8 {.exportc: "logos_shapes_module_MODULE_call_surface", dynlib, cdecl, gcsafe, raises: [].} =
    if outLen != nil:
      outLen[] = csize_t(callSurfaceData.len)
    addr callSurfaceData[0]

  proc shapesModuleKitFree(module: ptr LogosModuleContext, p: pointer) {.exportc: "logos_shapes_module_MODULE_free", dynlib, cdecl, gcsafe, raises: [].} =
    kitEnter()
    kitFree(module, p)

  proc shapesModuleKitDispatch(module: ptr LogosModuleContext, methodName: cstring, paramsCbor: ptr UncheckedArray[uint8], paramsLen: csize_t, outResponseCbor: ptr ptr UncheckedArray[uint8], outResponseLen: ptr csize_t): LogosResult {.exportc: "logos_shapes_module_MODULE_dispatch", dynlib, cdecl, gcsafe, raises: [].} =
    kitEnter()
    kitDispatch(module, methodName, paramsCbor, paramsLen, outResponseCbor, outResponseLen, shapesModuleKitRoute)

  proc shapesModuleKitCall0(p0: ptr LogosModuleContext, p1: ptr LogosResponseOwner, p2: ptr logos_shapes_Pick_request_t, p3: ptr logos_shapes_Pick_response_t): LogosResult {.exportc: "logos_shapes_module_CALL_shapes_Pick", dynlib, cdecl, gcsafe, raises: [].} =
    kitEnter()
    kitCall0[T](p0, p1, p2, p3)

  proc shapesModuleKitCall1(p0: ptr LogosModuleContext, p1: ptr LogosResponseOwner): LogosResult {.exportc: "logos_shapes_module_CALL_shapes_Ping", dynlib, cdecl, gcsafe, raises: [].} =
